from pathlib import Path
import base64,html,json,zipfile,hashlib,subprocess
O=Path(__file__).parent;R=Path('/home/user/repo')
q=json.loads((O/'evidence/summary.json').read_text());g=json.loads((O/'github-status.json').read_text())
scenes=[('catalog-loading','Загрузка каталога','Пока локальный индекс загружается, нет ложного сообщения об отсутствии товаров.'),('catalog-error','Ошибка и восстановление','Явный повтор без перезагрузки страницы. Состояние обновляется у всех потребителей каталога.'),('selection-empty','Выбранное без товаров','Вкладка сохраняет свой смысл. Перейти в каталог можно явным действием.'),('search-empty','Поиск без совпадений','Понятная подсказка и сброс запроса — без очистки выбранного оборудования.'),('lead-error','Ошибка отправки','Причина, сохранённые поля и прежний requestId для повтора.'),('lead-success','Заявка сохранена','Сохранение заявки не выдаётся за просмотр исполнителем. Номер остаётся в переписке.'),('rescue-error','Диалог на коротком экране','Действия переносятся, содержимое прокручивается, фокус возвращается к включённому повтору.')]
cards=[]
for name,title,desc in scenes:
 p=O/'screenshots'/f'{name}-chromium-mobile.png'
 data=base64.b64encode(p.read_bytes()).decode()
 cards.append(f'<article><div class="copy"><small>СОСТОЯНИЕ ИНТЕРФЕЙСА</small><h2>{html.escape(title)}</h2><p>{html.escape(desc)}</p></div><div class="visual"><img src="data:image/png;base64,{data}" alt="Тестовый снимок: {html.escape(title)}" loading="lazy"></div></article>')
css='''*{box-sizing:border-box}body{margin:0;background:#f6f5ef;color:#173c36;font:15px/1.7 Arial,sans-serif}header{background:#173c36;color:#f6f5ef;padding:54px max(22px,7vw)}header small{letter-spacing:2px;color:#d7ed89}h1{font-size:clamp(36px,5.3vw,62px);font-weight:400;line-height:1.08;letter-spacing:-2px;max-width:850px}header p{max-width:850px;color:#dbe1d8}main{max-width:1200px;margin:auto;padding:34px 22px}.facts{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:32px}.fact{background:#edf0e6;padding:20px;border-top:2px solid #a9844b}.fact b{font-size:28px;font-weight:500;display:block}.fact span{font-size:12px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px;align-items:start}article{border:1px solid #b6c3b4;border-radius:8px;overflow:hidden;break-inside:avoid}.copy{padding:24px}small{font-size:10px;letter-spacing:1.4px}h2{font-size:26px;font-weight:500;line-height:1.2;margin:10px 0 14px}.copy p{font-size:13px;color:#53675e;margin:0}.visual{padding:22px;background:#edf0e6}.visual img{display:block;width:100%;height:auto;max-width:390px;margin:auto;border-radius:5px}.note{border-left:3px solid #a9844b;padding:16px 20px;background:#edf0e6;margin-top:28px;font-size:13px}code{overflow-wrap:anywhere}footer{margin-top:28px;border-top:1px solid #b6c3b4;padding-top:18px;color:#53675e;font-size:12px}@media(max-width:650px){.grid,.facts{grid-template-columns:1fr}header{padding:34px 22px}.copy{padding:20px}.visual{padding:16px}}'''
e=q['e2e'];body=f'''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ПОТОЛКОВО · состояния интерфейса</title><style>{css}</style><header><small>ПОТОЛКОВО / B8-005 / PREVIEW</small><h1>Понятный<br>следующий шаг.</h1><p>Формы, каталог и диалог расчёта: одинаковый язык состояний, явное восстановление и сохранение контекста. Не новый редизайн с нуля.</p></header><main><div class="facts"><div class="fact"><b>{q['unit']['passed']}</b><span>unit-тестов с PostgreSQL · 0 пропусков</span></div><div class="fact"><b>{e['expected']}</b><span>E2E passed · {e['skipped']} прежних skips · 0 failed / flaky</span></div><div class="fact"><b>320 → 1440</b><span>адаптивность; короткий экран диалога 400 px</span></div></div><div class="grid">{''.join(cards)}</div><div class="note"><b>Что сохранено</b><p>Тарифы, расчётные формулы, URL, API, presets, согласие и идентификатор заявки. Проверены повтор отправки и восстановление каталога с существующей equipment-only корзиной. Новый SMART-подбор и reload автономной корзины не реализовывались.</p></div><div class="note"><b>Что ещё не принято</b><p>Реальные iPhone/Android, screen reader, экранная клавиатура и полная ручная проверка 200% zoom. Правовые/контентные допуски и разрешение production остаются отдельными задачами.</p></div><footer>14.10.2026 · Продуктовый код {q['productCommit'][:7]} · Отправленный коммит {g['head'][:7]}<br><code>feat/company-rebrand-v7-preview</code> · Main не изменён. На снимках тестовые заявки; реальные уведомления не отправлялись. Это обзор реализации, не ещё одно ТЗ.</footer></main></html>'''
(O/'POTOLKOVO-UI-STATES-V8.html').write_text(body)
entries=[(O/'POTOLKOVO-UI-STATES-V8.html','POTOLKOVO-UI-STATES-V8.html'),(R/'docs/current/UI-STATES.md','docs/current/UI-STATES.md'),(O/'evidence/summary.json','QA.json'),(O/'github-status.json','GIT.json')]
patch=subprocess.check_output(['git','diff','--binary','37405ed',g['head']],cwd=R);(O/'CHANGES.patch').write_bytes(patch);entries.append((O/'CHANGES.patch','CHANGES.patch'))
sums=''.join(hashlib.sha256(p.read_bytes()).hexdigest()+'  '+n+'\n' for p,n in entries)
with zipfile.ZipFile(O/'POTOLKOVO-UI-STATES-V8.zip','w',zipfile.ZIP_DEFLATED) as z:
 for p,n in entries:z.write(p,n)
 z.writestr('SHA256SUMS.txt',sums)
 z.writestr('README-FIRST.txt','Основной результат — HTML-обзор и коммиты preview-ветки. CHANGES.patch относится к базе 37405ed; не применять к main автоматически. Для полного набора актуальных ТЗ используйте docs/current в репозитории или POTOLKOVO-CURRENT-DOCS-V8.zip. Слияние и production-выпуск — только по отдельному разрешению владельца.\n')
with zipfile.ZipFile(O/'POTOLKOVO-UI-STATES-V8.zip') as z:
 assert z.testzip() is None
 for h,n in (line.split('  ',1) for line in sums.splitlines()):assert hashlib.sha256(z.read(n)).hexdigest()==h
print('Offline overview and verified UI-state handoff created.')
